exercises.solution:
using System;
using System.Collections.Generic;
using System.Linq;

public static class PerKg
{
    public static double PricePerKg(double total, double kg)
    {
        if (kg <= 0 || total < 0) throw new ArgumentException("bad input");
        return Math.Round(total / kg, 2);
    }
}
